  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_backup(q_cid, jsonb_build_object('kind', 'confined', 'lockTime', now(), 'space', 'MH-3'), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  select * into q_p from pb_safety.permits p where p.user_id = q_fm and p.client_permit_id = q_cid;
  perform pg_temp.q_ck('2s bad phoneAt: close-out ok, proof kept, clock empty, open row dropped',
    q_r->>'ok' = 'true' and q_p.open_saves = 1 and q_p.open_clock_ahead_s is null
    and not exists (select 1 from pb_safety.open_permits o where o.user_id = q_fm and o.client_permit_id = q_cid), q_r::text);
  -- a permit closed with no open snapshot on the server
  q_cid := 'cps-' || q_tag || '-4';
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_backup(q_cid, jsonb_build_object('kind', 'confined', 'lockTime', now(), 'space', 'MH-4'), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  select * into q_p from pb_safety.permits p where p.user_id = q_fm and p.client_permit_id = q_cid;
  perform pg_temp.q_ck('2t never saved open: close-out ok, proof columns empty', q_r->>'ok' = 'true' and q_p.open_saves is null and q_p.open_first_saved_at is null, q_r::text);
  -- SMOKE: the app paths r17.15 uses, after the change (permit open save + close-out, toolbox talk, daily report, run record)
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_open_put('cps-' || q_tag || '-s', jsonb_build_object('space', 'MH smoke', 'jobsite', 'Smoke site', 'jobNumber', 'Q-' || q_tag), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S1a app: open permit save (pb_permit_open_put) ok', q_r->>'ok' = 'true', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_backup('cps-' || q_tag || '-s', jsonb_build_object('kind', 'confined', 'lockTime', now(), 'space', 'MH smoke', 'jobNumber', 'Q-' || q_tag), q_fm, null::text); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S1b app: permit close-out backup (pb_permit_backup) ok, version 1', q_r->>'ok' = 'true' and q_r->>'version' = '1', q_r::text);
  perform pg_temp.q_ck('S1c app: open permit row dropped at close-out (as before)',
    not exists (select 1 from pb_safety.open_permits o where o.user_id = q_fm and o.client_permit_id = 'cps-' || q_tag || '-s'), '');
  q_id := gen_random_uuid();
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_talk_give(q_id, 'Q-' || q_tag, 'TT-001', 'Smoke talk', q_day, null, '[{"name":"Smoke One"}]'::jsonb, false, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S2a app: toolbox talk save (pb_talk_give) ok', q_r->>'ok' = 'true', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_talk_give(q_id, 'Q-' || q_tag, 'TT-001', 'Smoke talk', q_day, null, '[{"name":"Smoke One"},{"name":"Smoke Two"}]'::jsonb, false, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S2b app: toolbox talk edit ok, version 2', q_r->>'ok' = 'true' and q_r->'talk'->>'version' = '2', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_daily_submit('q-' || q_tag || '-ds', 'Q-' || q_tag || '-S', 'Smoke site', q_day,
      '{"events":[{"kind":"delay","reason":"weather","hours":1,"cid":"s1"}]}'::jsonb, encode(sha256('smoke'::bytea), 'hex'),
      'Smoke Foreman', now(), 'America/Los_Angeles', null, null, null, now(), true, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S3 app: daily report save (pb_daily_submit) ok with its delay entry', q_r->>'ok' = 'true' and q_r->>'events' = '1', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_prod_run_record_put('q-' || q_tag || '-rs', jsonb_build_object('kind', 'run', 'id', 'q-' || q_tag || '-rs', 'jobNumber', 'Q-' || q_tag,
      'lockTime', now(), 'startLabel', 'MH 1', 'endLabel', 'MH 2'), q_fm, q_co); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S4 app: run record save (pb_prod_run_record_put) ok, version 1', q_r->>'ok' = 'true' and q_r->>'version' = '1', q_r::text);
  -- undo 02: exact live text back; a close-out then works as before (proof not copied)
  q_b9 := exists (select 1 from pg_trigger t where t.tgname = 'open_permits_no_delete' and t.tgrelid = 'pb_safety.open_permits'::regclass);
  -- ===== undo 02 =====
-- undo records_nov22 Phase B 02 (B3): puts back pb_safety.drop_open_on_close exactly as it was live (saved by the guard
-- in pb_stage.fn_backup). The 5 copied columns on pb_safety.permits are KEPT on purpose (dropping them would lose proof
-- already copied; nothing reads them yet, and r17.15 / r17.16 never write them).
-- Undo 03 first if it is in: with B9 in and this undone, the close-out drop is refused by the guard, logged in
-- pb_prod.pass_errors, and the open row stays (the close-out itself still succeeds, nothing breaks for the crew).
-- Plain SQL, DO-block safe. Running it twice is harmless (second run restores nothing).
do $u$ declare n integer; begin
  n := pb_stage.restore('records_b3');
  raise notice 'records undo 02: % function(s) restored', n;
end $u$;

  perform pg_temp.q_ck('2u undo 02 puts back the exact live text', md5(pg_get_functiondef('pb_safety.drop_open_on_close()'::regprocedure)) = q_md5_before
    and not exists (select 1 from pb_stage.fn_backup b where b.tag = 'records_b3'), md5(pg_get_functiondef('pb_safety.drop_open_on_close()'::regprocedure)));
  q_cid := 'cps-' || q_tag || '-5';
  begin perform pg_temp.q_as(q_fm); q_r := public.pb_permit_open_put(q_cid, jsonb_build_object('space', 'MH-5'), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_backup(q_cid, jsonb_build_object('kind', 'confined', 'lockTime', now(), 'space', 'MH-5'), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  select * into q_p from pb_safety.permits p where p.user_id = q_fm and p.client_permit_id = q_cid;
  perform pg_temp.q_ck('2v after undo: close-out ok, proof not copied, open row ' || case when q_b9 then 'kept (03 is in: undo 03 first)' else 'dropped (as before)' end,
    q_r->>'ok' = 'true' and q_p.open_saves is null
    and exists (select 1 from pb_safety.open_permits o where o.user_id = q_fm and o.client_permit_id = q_cid) = q_b9, q_r::text);
  select count(*) filter (where c.ok), count(*) filter (where c.ok is not true),
         coalesce(string_agg(c.name || ' [got: ' || coalesce(c.got, 'null') || ']', ' ; ' order by c.i) filter (where c.ok is not true), '')
    into q_pass, q_fail, q_fails from pg_temp.q_chk c;
  raise exception 'RESULT: % pass, % fail% %', q_pass, q_fail, case when q_fail > 0 then ' | FAILED: ' || q_fails else '' end, q_notes;
end $T$;
